/**
 * Objective-C header export
 *
 * Generates standalone .h files from decoded class and protocol metadata.
 * Files are written flat into the user-selected directory.
 */

import type {
	ObjCCategory,
	ObjCClass,
	ObjCIvar,
	ObjCMethod,
	ObjCProperty,
	ObjCProtocol
} from "../../shared/types";

export interface HeaderExportInput {
	classes: ObjCClass[];
	categories?: ObjCCategory[];
	protocols: string[];
	protocolDetails: ObjCProtocol[];
	/** Binary name shown in the generated file banners. */
	binaryName?: string;
}

export interface HeaderFile {
	name: string;
	content: string;
}

/** Method signatures can be decorated with a trailing semicolon after enrichment. */
function methodDeclaration(method: ObjCMethod): string | null {
	// A method whose selector was never recovered (shared-cache selector pool absent)
	// can't be written as a valid declaration — its signature is only a decoded prototype.
	if (!method.selector?.trim()) return null;
	const signature = (method.signature || method.selector || "").trim();
	if (!signature) return null;

	let declaration = signature;
	if (!declaration.startsWith("-") && !declaration.startsWith("+")) {
		const selector = method.selector?.trim();
		if (!selector) return null;
		declaration = `-(id)${selector}`;
	}
	declaration = declaration.replace(/;\s*$/, "").trim();
	return declaration ? `${declaration};` : null;
}

/** Join a type and a name with a space unless the type ends in a pointer star. */
function typedName(type: string, name: string): string {
	const t = type.trim() || "id";
	return t.endsWith("*") ? `${t}${name}` : `${t} ${name}`;
}

/**
 * Render declarations with their trailing `// comment` aligned to the longest declaration
 * that carries one. Declarations without a comment are emitted as-is (no trailing padding).
 */
function withAlignedComments(entries: { decl: string; comment?: string }[]): string[] {
	const commented = entries.filter((e) => e.comment);
	const width = commented.length > 0 ? Math.max(...commented.map((e) => e.decl.length)) : 0;
	return entries.map((e) => (e.comment ? `${e.decl.padEnd(width)}  // ${e.comment}` : e.decl));
}

/** `@property (attrs) Type name;` */
function propertyDeclaration(property: ObjCProperty): string {
	const attrs =
		property.attributeList.length > 0 ? ` (${property.attributeList.join(", ")})` : "";
	return `@property${attrs} ${typedName(property.type, property.name)};`;
}

/** Sorted, de-duplicated property declarations, each annotated with its backing ivar. */
function propertyDeclarations(properties: ObjCProperty[] | undefined): string[] {
	const seen = new Set<string>();
	const entries: { decl: string; comment?: string }[] = [];
	for (const property of properties ?? []) {
		if (!property.name) continue;
		const decl = propertyDeclaration(property);
		if (seen.has(decl)) continue;
		seen.add(decl);
		entries.push({ decl, comment: property.ivar ? `ivar: ${property.ivar}` : undefined });
	}
	entries.sort((a, b) => a.decl.localeCompare(b.decl));
	return withAlignedComments(entries);
}

/** Ivar block lines (`Type _name;  // offset: +0xN`) wrapped in braces, or [] when none. */
function ivarBlock(ivars: ObjCIvar[] | undefined): string[] {
	const seen = new Set<string>();
	const entries: { decl: string; comment?: string }[] = [];
	for (const ivar of ivars ?? []) {
		if (!ivar.name) continue;
		const decl = `    ${typedName(ivar.type, ivar.name)};`;
		if (seen.has(decl)) continue;
		seen.add(decl);
		entries.push({ decl, comment: `offset: +0x${ivar.offset.toString(16)}` });
	}
	if (entries.length === 0) return [];
	return ["{", ...withAlignedComments(entries), "}"];
}

/** Sorted, de-duplicated method declarations, split into class (+) and instance (-). */
function splitMethodDeclarations(methods: ObjCMethod[] | undefined): {
	classMethods: string[];
	instanceMethods: string[];
} {
	const seen = new Set<string>();
	const classMethods: string[] = [];
	const instanceMethods: string[] = [];
	for (const method of methods ?? []) {
		const declaration = methodDeclaration(method);
		if (!declaration || seen.has(declaration)) continue;
		seen.add(declaration);
		(declaration.startsWith("+") ? classMethods : instanceMethods).push(declaration);
	}
	classMethods.sort((a, b) => a.localeCompare(b));
	instanceMethods.sort((a, b) => a.localeCompare(b));
	return { classMethods, instanceMethods };
}

/** Sorted, de-duplicated method declarations (class methods first, then instance). */
function methodDeclarations(methods: ObjCMethod[] | undefined): string[] {
	const { classMethods, instanceMethods } = splitMethodDeclarations(methods);
	return [...classMethods, ...instanceMethods];
}

function sanitiseFileName(name: string): string {
	// "+" is kept so categories export as the class-dump "Class+Category.h" form.
	const safe = name.replace(/[^A-Za-z0-9_.+-]/g, "_");
	return safe || "Unnamed";
}

function banner(fileName: string, binaryName?: string): string[] {
	const lines = ["//", `//  ${fileName}`, "//  Generated by AppInspect"];
	if (binaryName) lines.push(`//  Binary: ${binaryName}`);
	lines.push("//", "");
	return lines;
}

function importSection(imports: string[], classForwards: string[], protocolForwards: string[]) {
	const lines: string[] = ["#import <Foundation/Foundation.h>"];
	for (const file of imports.sort()) lines.push(`#import "${file}"`);
	if (imports.length > 0) lines.push("");

	for (const name of classForwards.sort()) lines.push(`@class ${name};`);
	for (const name of protocolForwards.sort()) lines.push(`@protocol ${name};`);
	if (classForwards.length > 0 || protocolForwards.length > 0) lines.push("");

	return lines;
}

/**
 * Append an interface body — the ivar block, then the property, class-method and
 * instance-method sections — separating sections with a blank line but never leading the
 * first one that appears with a blank.
 */
function appendInterfaceBody(
	lines: string[],
	sections: {
		ivars: string[];
		properties: string[];
		classMethods: string[];
		instanceMethods: string[];
	}
): void {
	let wrote = false;
	if (sections.ivars.length > 0) {
		for (const line of sections.ivars) lines.push(line);
		wrote = true;
	}
	for (const group of [sections.properties, sections.classMethods, sections.instanceMethods]) {
		if (group.length === 0) continue;
		if (wrote) lines.push("");
		for (const item of group) lines.push(item);
		wrote = true;
	}
}

function classHeader(
	cls: ObjCClass,
	fileName: string,
	classFiles: Map<string, string>,
	protocolFiles: Map<string, string>,
	binaryName?: string
): string {
	const imports: string[] = [];
	const classForwards: string[] = [];
	const protocolForwards: string[] = [];
	const protocols = [...new Set((cls.protocols ?? []).filter(Boolean))].sort((a, b) =>
		a.localeCompare(b)
	);

	const superclass = cls.superclass?.trim();
	if (superclass) {
		const superFile = classFiles.get(superclass);
		if (superFile) imports.push(superFile);
		else classForwards.push(superclass);
	}

	for (const protocol of protocols) {
		const protocolFile = protocolFiles.get(protocol);
		if (protocolFile) imports.push(protocolFile);
		else protocolForwards.push(protocol);
	}

	const lines = banner(fileName, binaryName);
	lines.push(...importSection(imports, classForwards, protocolForwards));

	let declaration = `@interface ${cls.name}`;
	if (superclass) declaration += ` : ${superclass}`;
	if (protocols.length > 0) declaration += ` <${protocols.join(", ")}>`;
	lines.push(declaration);

	const { classMethods, instanceMethods } = splitMethodDeclarations(cls.methods);
	appendInterfaceBody(lines, {
		ivars: ivarBlock(cls.ivars),
		properties: propertyDeclarations(cls.properties),
		classMethods,
		instanceMethods
	});
	lines.push("@end", "");
	return lines.join("\n");
}

/** Build a category header: `@interface Class (Category) ... @end`. */
function categoryHeader(category: ObjCCategory, fileName: string, binaryName?: string): string {
	const protocols = [...new Set(category.protocols.filter(Boolean))].sort((a, b) =>
		a.localeCompare(b)
	);

	const lines = banner(fileName, binaryName);
	lines.push("#import <Foundation/Foundation.h>", "");
	if (category.className) lines.push(`@class ${category.className};`);
	for (const name of protocols) lines.push(`@protocol ${name};`);
	if (category.className || protocols.length > 0) lines.push("");

	let declaration = `@interface ${category.className} (${category.name})`;
	if (protocols.length > 0) declaration += ` <${protocols.join(", ")}>`;
	lines.push(declaration);

	const { classMethods, instanceMethods } = splitMethodDeclarations(category.methods);
	appendInterfaceBody(lines, {
		ivars: [],
		properties: propertyDeclarations(category.properties),
		classMethods,
		instanceMethods
	});
	lines.push("@end", "");
	return lines.join("\n");
}

function protocolHeader(
	protocol: ObjCProtocol | null,
	name: string,
	fileName: string,
	binaryName?: string
): string {
	const lines = banner(fileName, binaryName);
	lines.push("#import <Foundation/Foundation.h>", "");
	lines.push(`@protocol ${name}`, "");

	const groups: { label: string; methods: ObjCMethod[] | undefined }[] = protocol
		? [
				{ label: "@required", methods: protocol.instanceMethods },
				{ label: "@required", methods: protocol.classMethods },
				{ label: "@optional", methods: protocol.optionalInstanceMethods },
				{ label: "@optional", methods: protocol.optionalClassMethods }
			]
		: [];

	let lastLabel = "";
	for (const group of groups) {
		const methods = methodDeclarations(group.methods);
		if (methods.length === 0) continue;
		if (group.label !== lastLabel) {
			lines.push(group.label);
			lastLabel = group.label;
		}
		for (const method of methods) lines.push(method);
	}

	lines.push("@end", "");
	return lines.join("\n");
}

/** Allocate a unique, filesystem-safe file name per exported symbol. */
function allocator(): (base: string) => string {
	const used = new Set<string>();
	return (base: string) => {
		const safe = sanitiseFileName(base);
		let candidate = `${safe}.h`;
		for (let i = 2; used.has(candidate.toLowerCase()); i++) {
			candidate = `${safe}-${i}.h`;
		}
		used.add(candidate.toLowerCase());
		return candidate;
	};
}

/**
 * Build the header files for one binary. Protocols come first so class headers
 * can import the definitions they conform to.
 */
export function buildHeaders({
	classes,
	categories,
	protocols,
	protocolDetails,
	binaryName
}: HeaderExportInput): HeaderFile[] {
	const classMap = new Map<string, ObjCClass>();
	for (const cls of classes ?? []) {
		if (!cls.name || classMap.has(cls.name)) continue;
		classMap.set(cls.name, cls);
	}

	const protocolMap = new Map<string, ObjCProtocol>();
	for (const protocol of protocolDetails ?? []) {
		if (!protocol.name || protocolMap.has(protocol.name)) continue;
		protocolMap.set(protocol.name, protocol);
	}
	const protocolNames = new Set<string>([
		...(protocols ?? []).filter(Boolean),
		...protocolMap.keys()
	]);

	const allocate = allocator();
	const protocolFiles = new Map<string, string>();
	const classFiles = new Map<string, string>();

	const sortedProtocols = [...protocolNames].sort((a, b) => a.localeCompare(b));
	for (const name of sortedProtocols) protocolFiles.set(name, allocate(name));

	const sortedClasses = [...classMap.keys()].sort((a, b) => a.localeCompare(b));
	for (const name of sortedClasses) classFiles.set(name, allocate(name));

	const files: HeaderFile[] = [];

	for (const name of sortedProtocols) {
		const fileName = protocolFiles.get(name)!;
		files.push({
			name: fileName,
			content: protocolHeader(protocolMap.get(name) ?? null, name, fileName, binaryName)
		});
	}

	for (const name of sortedClasses) {
		const fileName = classFiles.get(name)!;
		files.push({
			name: fileName,
			content: classHeader(
				classMap.get(name)!,
				fileName,
				classFiles,
				protocolFiles,
				binaryName
			)
		});
	}

	const sortedCategories = [...(categories ?? [])]
		.filter((category) => category.name)
		.sort((a, b) => `${a.className}+${a.name}`.localeCompare(`${b.className}+${b.name}`));
	for (const category of sortedCategories) {
		const fileName = allocate(`${category.className}+${category.name}`);
		files.push({ name: fileName, content: categoryHeader(category, fileName, binaryName) });
	}

	return files;
}
